patch:
diff --git a/repro.cjs b/repro.cjs
new file mode 100644
index 0000000..86cc5d2
--- /dev/null
+++ b/repro.cjs
@@ -0,0 +1,75 @@
+/*
+ * Reproduction for eslint/eslint#18575:
+ * "files on a different drive are not ignored on Windows"
+ *
+ * This machine is Linux, so we simulate Windows path semantics by
+ * monkeypatching the `node:path` module singleton with `path.win32`
+ * after eslint is loaded but before the lint call. Since every module
+ * shares that singleton, `path.relative()`, `path.sep`, etc. inside
+ * eslint and @eslint/config-array then behave as on win32 (drive
+ * letters, `relative()` across drives returning the absolute target).
+ *
+ * On real Windows, from C:\Project:
+ *   npx eslint --no-config-lookup F:\foo.js      -> file is linted (BUG)
+ * and:
+ *   new Linter({ configType: "flat" })
+ *       .verify("foo()", { rules: { "no-undef": "error" } }, "F:\\foo.js")
+ *   -> returns the no-undef error instead of reporting the file ignored.
+ */
+
+"use strict";
+
+const path = require("node:path");
+const { Linter } = require("./lib/linter");
+
+// Warm up lazy require()s (rules are loaded on demand via require())
+// using a throwaway linter with a real (posix) cwd so the config matches.
+new Linter({ configType: "flat" }).verify(
+    "foo()",
+    { rules: { "no-undef": "error" } },
+    "foo.js"
+);
+
+const linter = new Linter({ configType: "flat", cwd: "C:\\Project" });
+
+// Swap the posix path implementation for the win32 one, in place.
+const win32 = path.win32;
+
+for (const key of Reflect.ownKeys(win32)) {
+    if (key === "win32" || key === "posix") {
+        continue;
+    }
+    const descriptor = Object.getOwnPropertyDescriptor(win32, key);
+    Object.defineProperty(path, key, descriptor);
+}
+
+// Control: a file outside the base path but on the SAME drive is ignored.
+const control = linter.verify(
+    "foo()",
+    { rules: { "no-undef": "error" } },
+    "C:\\Other\\bar.js"
+);
+
+console.log("--- same-drive control (C:\\Other\\bar.js) ---");
+console.log(JSON.stringify(control, null, 2));
+
+// Bug: a file on a DIFFERENT drive is linted instead of ignored.
+const results = linter.verify(
+    "foo()",
+    { rules: { "no-undef": "error" } },
+    "F:\\foo.js"
+);
+
+console.log("--- different drive (F:\\foo.js) ---");
+console.log(JSON.stringify(results, null, 2));
+
+const linted = results.some(
+    message => message.ruleId === "no-undef" && message.severity === 2
+);
+
+if (linted) {
+    console.log("\nBUG REPRODUCED: F:\\foo.js was linted instead of ignored.");
+    process.exitCode = 1;
+} else {
+    console.log("\nOK: F:\\foo.js was treated as ignored.");
+}
